-- seed_branches.sql — 공공데이터 상가(상권)정보에서 뽑은 브랜드 지점 (scripts/import/build-branches.mjs 가 생성, 직접 수정하지 않는다)
-- 원본: 소상공인시장진흥공단_상가(상권)정보_서울_202609.csv / 브랜드: 맥도날드, 롯데리아, 버거킹, BBQ, 피자헛, 파파존스 / 지점 747개
-- 멱등: 여러 번 실행해도 안전하다 (brands 는 이름, restaurants 는 external_id 로 upsert).
-- 같은 (브랜드, 도로명주소) 지점은 1행만 남긴다. 정리 단계가 이번 목록에 없는 대상 브랜드의 지점을 삭제한다.
-- 주의: 중복 행 삭제로 사용자가 저장한 가게(saved_restaurants, on delete cascade)의 일부가 함께 사라질 수 있다.
-- 실행 순서: (schema/policies/functions/seed_reference 이후) 이 파일 → seed_brand_menus.sql
-- =====================================================================
begin;

-- 브랜드: 맥도날드
insert into brands (name, is_franchise, category_id, official_domains)
values ('맥도날드', true, (select id from food_categories where name = '양식'), array['mcdonalds.co.kr']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

-- 브랜드: 롯데리아
insert into brands (name, is_franchise, category_id, official_domains)
values ('롯데리아', true, (select id from food_categories where name = '양식'), array['lotteeatz.com']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

-- 브랜드: 버거킹
