values ('버거킹', true, (select id from food_categories where name = '양식'), array['burgerking.co.kr']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

-- 브랜드: BBQ
insert into brands (name, is_franchise, category_id, official_domains)
values ('BBQ', true, (select id from food_categories where name = '양식'), array['bbq.co.kr']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

-- 브랜드: 피자헛
insert into brands (name, is_franchise, category_id, official_domains)
values ('피자헛', true, (select id from food_categories where name = '양식'), array['pizzahut.co.kr']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

-- 브랜드: 파파존스
insert into brands (name, is_franchise, category_id, official_domains)
values ('파파존스', true, (select id from food_categories where name = '양식'), array['pji.co.kr']::text[])
on conflict (name) where is_franchise do update
  set is_franchise = true, category_id = excluded.category_id, official_domains = excluded.official_domains;

